starterCode:
LOAD spatial;

-- Find the 5 nearest coffee shops to user id = 1.
-- Return: shop_name, dist_km (rounded to 2dp) ordered nearest-first

setup:
CREATE TABLE users AS SELECT * FROM (VALUES
  (1, 40.7128, -74.0060),
  (2, 40.7580, -73.9855)
) t(id, lat, lng);

CREATE TABLE shops AS SELECT * FROM (VALUES
  (1, 'Brew & Co.',        ST_Point(-74.0032, 40.7100)),
  (2, 'The Daily Grind',   ST_Point(-74.0150, 40.7200)),
  (3, 'Espresso Republic', ST_Point(-73.9950, 40.7300)),
  (4, 'Roast & Toast',     ST_Point(-74.0200, 40.6980)),
  (5, 'Bean Scene',        ST_Point(-73.9800, 40.7050)),
  (6, 'North Grind',       ST_Point(-74.0400, 40.7500))
) t(shop_id, shop_name, geom);
